import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Projects","description":"","frontmatter":{"source":"projects/README.md"},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md"}'),s={name:"projects/index.md"};function n(d,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><blockquote><p>Five things you build and ship, in four repositories. Each one is live on the public web, and each one adds a habit the next one needs.</p></blockquote><p>You will build a personal page, a game, a tool you actually use, a small AI-powered app and a capstone of your choice. Each project lives in its own GitHub <strong>repository</strong> (repo: a project folder that git tracks, stored on GitHub), and each is <strong>deployed</strong> (published so anyone with the link can use it). New words are explained in the <a href="./../resources/glossary.html">glossary</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project</th><th>Weeks</th><th>What you build</th><th>Where it lives</th><th>Starter</th><th>Due</th></tr></thead><tbody><tr><td><a href="./home-page.html">Home page</a></td><td>1–4</td><td>A personal page (weeks 1–2), plus a browser game in <code>/game/</code> (weeks 3–4)</td><td>Repo named <code>[username].github.io</code>, on GitHub Pages</td><td>None. You start in a chat assistant</td><td>Page live: end of week 2 · Game: in the week 3 and week 4 homework</td></tr><tr><td><a href="./project-1-useful-tool.html">Project 1: A Tool I&#39;d Actually Use</a></td><td>5–8</td><td>A single-user web tool built from your own spec, saving its data in the browser, with automated tests of its logic</td><td>Its own repo, on GitHub Pages</td><td>None. You build from your own <code>SPEC.md</code></td><td>v1: end of week 6 · Final: end of week 8</td></tr><tr><td><a href="./ai-micro-app.html">Project 2: An AI Micro-App</a></td><td>9–10</td><td>A small app that asks an LLM for help from a server route, with the key kept secret</td><td>Its own repo, on Vercel</td><td><code>weeks/09-apis-and-secrets/starter/</code></td><td>End of week 10</td></tr><tr><td><a href="./capstone.html#the-pitch">Capstone pitch</a></td><td>10</td><td>One paragraph, a sketch, your feature choices and your biggest risk</td><td>Canvas</td><td>None</td><td><strong>72 hours before week 11 Studio A</strong></td></tr><tr><td><a href="./capstone.html">Capstone</a></td><td>11–16</td><td>A deployed full-stack web app of your choice, built with an AI agent</td><td>Its own repo, on Vercel (plus Supabase if it stores shared data)</td><td><code>projects/capstone-starter/</code></td><td><a href="./capstone.html#milestones">Milestones</a>: end of weeks 12 and 14 · Final: at the start of the final exam period, when you present</td></tr></tbody></table><p><strong>&quot;End of week N&quot;</strong> means <strong>before week N+1&#39;s Studio A (default 11:59 pm the night before)</strong>, unless Canvas, the course&#39;s learning management system, says otherwise. The capstone final is due at the start of the course&#39;s scheduled final exam period in finals week, posted on Canvas: the production URL and screenshot, the repo and the final commit, and the final reflection with your revised AI-use rules. In that period you give a <a href="./../weeks/16-final-presentations/">five-minute presentation</a> with a live demo.</p><p>Need an idea for the capstone? See <a href="./capstone-ideas.html">Capstone Ideas</a>.</p><h3 id="how-each-project-is-graded" tabindex="-1">How each project is graded <a class="header-anchor" href="#how-each-project-is-graded" aria-label="Permalink to &quot;How each project is graded&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Project</th><th>Counts toward</th><th>Rubric</th></tr></thead><tbody><tr><td>Home page</td><td>Assignments (the weeks 1–4 homework)</td><td><a href="./../assessment/rubrics.html#assignments">Assignments rubric</a></td></tr><tr><td>Project 1</td><td>Project 1 (15%)</td><td><a href="./../assessment/rubrics.html#project-1">Project 1 rubric</a></td></tr><tr><td>Project 2 (AI micro-app)</td><td>Project 2 (15%); it is your homework for weeks 9 and 10</td><td><a href="./../assessment/rubrics.html#project-2">Project 2 rubric</a></td></tr><tr><td>Capstone pitch</td><td>Assignments (week 10)</td><td><a href="./../assessment/rubrics.html#capstone-pitch">Capstone pitch rubric</a></td></tr><tr><td>Capstone</td><td>Capstone (30%); Milestone 1 is your week 12 homework, and Milestone 2 your week 13 and 14 homework</td><td><a href="./../assessment/rubrics.html#capstone">Capstone rubric</a></td></tr></tbody></table><p>After your final presentation you answer questions about your capstone&#39;s code, with the AI off. Full details: <a href="./../assessment/">Assessment</a>.</p><h2 id="the-three-project-rules" tabindex="-1">The three project rules <a class="header-anchor" href="#the-three-project-rules" aria-label="Permalink to &quot;The three project rules&quot;">​</a></h2><p>These apply to every project, including stretch work. They come from the <a href="./../setup/safety-contract.html">safety contract</a>.</p><ol><li><strong>No real payments.</strong> Free hosting tiers forbid commercial use (<a href="https://vercel.com/docs/plans/hobby" target="_blank" rel="noreferrer">Vercel Hobby</a>; <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/github-pages-limits" target="_blank" rel="noreferrer">GitHub Pages</a>), and payment code is high-stakes. A &quot;Buy&quot; button that does nothing real is fine for a demo.</li><li><strong>No real personal data about other people.</strong> Use made-up names, emails and entries. Free AI tiers may train on what you type, and a single missing database rule can make everything public.</li><li><strong>Nothing you would miss if an AI agent deleted it.</strong> Keep real documents, photos and work files out of your project folders. AI agents have deleted files and databases they were not supposed to touch (<a href="./../resources/case-studies.html">case studies</a>).</li></ol><p>If you are not sure whether an idea breaks a rule, ask before you build it.</p><h2 id="what-goes-in-a-repo-and-what-goes-on-canvas" tabindex="-1">What goes in a repo, and what goes on Canvas <a class="header-anchor" href="#what-goes-in-a-repo-and-what-goes-on-canvas" aria-label="Permalink to &quot;What goes in a repo, and what goes on Canvas&quot;">​</a></h2><p>Your project repos are public: they become your portfolio. Your grades and personal writing stay private, on Canvas.</p><ul><li><strong>In your repos:</strong> code, <code>SPEC.md</code>, <code>TESTS.md</code>, <code>PROMPTS.md</code>, <code>AGENTS.md</code>, <code>SECURITY_CHECKLIST.md</code>, <code>README.md</code>, and screenshots of your app with made-up data.</li><li><strong>On Canvas only:</strong> reflections, exit tickets, your personal AI-use rules, the signed safety contract, self-assessments, written peer reviews, a pair&#39;s signed contribution statement, the capstone pitch, and your project submissions.</li><li><strong>Never commit</strong> grades, feedback, reflections, classmates&#39; real names (use GitHub usernames), your student ID or anyone&#39;s real personal data.</li></ul><p>The reasons, and the University policies behind them, are in <a href="./../assessment/#privacy-of-your-work">Privacy of your work</a>.</p><h2 id="naming-conventions" tabindex="-1">Naming conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming conventions&quot;">​</a></h2><p>Consistent names make your work easy to find, grade and show off.</p><table tabindex="0"><thead><tr><th>Thing</th><th>Convention</th><th>Example</th></tr></thead><tbody><tr><td>Home page repo</td><td>Exactly <code>[username].github.io</code> (GitHub requires this)</td><td><code>adalovelace.github.io</code></td></tr><tr><td>Project 1, Project 2 and capstone repos</td><td>Named after what the app does</td><td><code>plant-tracker</code>, <code>fridge-chef</code>, <code>study-buddy</code></td></tr><tr><td>Course documents</td><td>Exactly these names, at the top level of the repo: <code>README.md</code>, <code>SPEC.md</code>, <code>TESTS.md</code>, <code>PROMPTS.md</code>, <code>AGENTS.md</code>, <code>SECURITY_CHECKLIST.md</code></td><td><code>SPEC.md</code>, not <code>spec-final-v2.md</code></td></tr><tr><td>Images and other supporting files</td><td>In a <code>docs/</code> folder</td><td><code>docs/wireframe.jpg</code>, <code>docs/screenshot.png</code></td></tr><tr><td>Commit messages</td><td>Start with a verb and say what changed. If AI helped, end with an <code>Assisted-by: [tool]</code> line (taught in week 3, required from week 11)</td><td><code>Add delete button to each task</code></td></tr><tr><td>Branches (week 12 on)</td><td><code>feature/[short-name]</code> or <code>fix/[short-name]</code></td><td><code>feature/weekly-chart</code></td></tr></tbody></table><p>Repo names use lowercase letters, numbers and hyphens only. No spaces, and nothing personal such as your birth year or student ID. If you like, add a prefix such as <code>capstone-</code> to keep your list of repos tidy.</p><h2 id="templates-and-starters" tabindex="-1">Templates and starters <a class="header-anchor" href="#templates-and-starters" aria-label="Permalink to &quot;Templates and starters&quot;">​</a></h2><ul><li><strong>Document templates:</strong> <a href="./../templates/SPEC.html">SPEC</a> · <a href="./../templates/TESTS.html">TESTS</a> · <a href="./../templates/PROMPTS.html">PROMPTS</a> · <a href="./../templates/PROJECT_README.html">PROJECT_README</a> · <a href="./../templates/AGENTS.html">AGENTS</a> · <a href="./../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST</a> · <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW</a> · <a href="./../templates/REFLECTION.html">REFLECTION</a>. Copy a template into your repo and fill it in. (The reflection template is a shape for writing you submit on Canvas, not a file for your repo.)</li><li><strong>Starter kits:</strong> Project 2, the AI micro-app, starts from <a href="https://github.com/Boyu-Zhang-UOI/vc101-micro-app-starter" target="_blank" rel="noreferrer"><code>weeks/09-apis-and-secrets/starter/</code></a>, and the capstone from <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter" target="_blank" rel="noreferrer"><code>projects/capstone-starter/</code></a>. The capstone starter already contains the document templates, adapted for the capstone, and tested <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a> for a database, a chart and a public API. How to copy a starter into your own repo: <a href="./../setup/codespaces.html#start-a-project-from-a-starter">Start a project from a starter</a>.</li><li><strong>Fallen behind on Project 1?</strong> The <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a> is a working study timer in plain HTML, CSS and JavaScript, built from the <a href="./../weeks/05-spec-first/example-spec.html">week 5 example spec</a>. If your own v1 doesn&#39;t work by week 7, talk to your instructor: you can continue from the rescue starter so you can still take part in weeks 7 and 8 (debugging, the function you write yourself and tests). Credit it in your README and <code>PROMPTS.md</code>; your own additions and documents are what&#39;s graded.</li></ul><h2 id="how-to-submit" tabindex="-1">How to submit <a class="header-anchor" href="#how-to-submit" aria-label="Permalink to &quot;How to submit&quot;">​</a></h2><p>Do this for every project deadline.</p><ol><li><p><strong>Save everything to GitHub.</strong> Commit your work, then open your repo on github.com and check that your latest commit is there.</p></li><li><p><strong>Test the live site as a stranger would.</strong> Open the live URL in a private (incognito) window. If it only works on your computer, it isn&#39;t done.</p></li><li><p><strong>From week 10 (Vercel): use the production URL and take a screenshot.</strong> The production URL is your app&#39;s main, permanent address (for example <code>https://fridge-chef.vercel.app</code>), not a long preview link: Vercel deletes old preview deployments. Take a screenshot of the production site working.</p></li><li><p><strong>Copy the link to your final commit.</strong> On your repo page on GitHub, open the commit history (the clock icon or &quot;N commits&quot;), click the top commit, and copy the address from the browser bar. Menus move; if you can&#39;t find it, ask your chat assistant &quot;How do I get the link to a specific commit on GitHub?&quot;</p></li><li><p><strong>Submit on Canvas:</strong></p><ul><li>the repo URL;</li><li>the live URL (from week 10, the production URL <strong>and the screenshot</strong>);</li><li>the link to your final commit.</li></ul><p>Reflections, peer reviews and other personal writing are separate Canvas assignments. They never go in the repo.</p></li></ol><p>We grade the commit you submitted. You can keep working afterwards, but later commits only count if you resubmit before the deadline (or before your extended deadline if you use a <a href="./../assessment/#late-work-and-grace-tokens">grace token</a>).</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Keep project repos <strong>public</strong> unless you have a reason not to. GitHub Pages on a free account needs a public repo. A private repo is fine for the micro-app and capstone if it&#39;s on your <strong>personal</strong> account (Vercel&#39;s free plan can&#39;t deploy private repos owned by an organization) and you add your instructor as a collaborator. Public means <strong>anyone</strong> can read every file and every old commit, which is one more reason never to commit a secret.</p></div><p><strong>Learning on your own?</strong> Add a link to each finished project on your home page. That list becomes your portfolio.</p>',30)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
